    /// A temporary file that deletes itself on dispose.
    /// </summary>
    private sealed class TempFile(string path) : IDisposable
    {
        public string Path => path;

        public void Dispose()
        {
            try { File.Delete(Path); }
            catch { /* best-effort */ }
        }
    }
